// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    StaxLPStaking c;

    function setUp() public {
        c = new StaxLPStaking(address(this), address(this));
    }

    function _run(address caller, address distributor) internal {
        vm.assume(caller != address(0));
        try c.setRewardDistributor(distributor) {} catch { return; }
        address stored;
        try c.rewardDistributor() returns (address __r) { stored = __r; } catch { return; }
        assertTrue(stored == distributor);
    }

    function testFuzz_run(address caller, address distributor) public {
        _run(caller, distributor);
    }

    receive() external payable {}
}
